def leadsToDestination(n, edges, source, destination):
    import sys
    from collections import defaultdict
    sys.setrecursionlimit(max(1000, 2 * n + 100))  # n can reach 10^4, so the DFS may go deep

    # Build adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    state = [0] * n  # 0=unvisited, 1=visiting, 2=safe

    def dfs(node):
        if state[node] == 1:
            # Detected a cycle
            return False
        if state[node] == 2:
            # Already confirmed safe
            return True
        if not graph[node]:
            # Dead end: must be destination
            return node == destination
        state[node] = 1  # Mark as visiting
        for nei in graph[node]:
            if not dfs(nei):
                return False
        state[node] = 2  # Mark as safe
        return True

    return dfs(source)
